const DEFAULT_BASE = 'https://email-worker.torarnehave.workers.dev';

const resolveBase = (baseUrl) => (baseUrl ? baseUrl.replace(/\/+$/, '') : DEFAULT_BASE);

export const sendMagicLink = async ({ email, redirectUrl, baseUrl } = {}) => {
  if (!email) {
    throw new Error('Email is required.');
  }
  const base = resolveBase(baseUrl);
  const payload = { email };
  if (redirectUrl) {
    payload.redirectUrl = redirectUrl;
  }
  const res = await fetch(`${base}/login/magic/send`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  });
  const data = await res.json();
  if (!res.ok || !data.success) {
    throw new Error(data.error || 'Failed to send magic link.');
  }
  return data;
};

export const verifyMagicLink = async ({ token, baseUrl } = {}) => {
  if (!token) {
    throw new Error('Token is required.');
  }
  const base = resolveBase(baseUrl);
  const res = await fetch(
    `${base}/login/magic/verify?token=${encodeURIComponent(token)}`,
    { method: 'GET', headers: { 'Content-Type': 'application/json' } }
  );
  const data = await res.json();
  if (!res.ok || !data.success) {
    throw new Error(data.error || 'Invalid or expired magic link.');
  }
  return data;
};

export const parseMagicToken = (url = window.location.href) => {
  try {
    const parsed = new URL(url);
    return parsed.searchParams.get('magic');
  } catch {
    return null;
  }
};

export const persistUser = (user) => {
  if (!user || !user.email) return null;
  const payload = {
    email: user.email,
    role: user.role || null,
    user_id: user.user_id || null,
    oauth_id: user.oauth_id || user.user_id || null,
    emailVerificationToken: user.emailVerificationToken || null,
    phone: user.phone || null,
    phoneVerifiedAt: user.phoneVerifiedAt || null,
    branding: user.branding || { mySite: null, myLogo: null },
    profileimage: user.profileimage || null
  };
  try {
    localStorage.setItem('user', JSON.stringify(payload));
  } catch {
    return null;
  }
  return payload;
};
